  assert(serialized.includes('"Article"'), "thirty-ninth JSON-LD Article");
  assert(serialized.includes('"WebPage"'), "thirty-ninth JSON-LD WebPage");
  assert(serialized.includes('"Organization"'), "thirty-ninth JSON-LD Organization");
