function testFortiethPage() {
  const parsed = parseListenPageDefinition(
    MUZYKA_DLYA_SNA_DLYA_MALYSHEY_SLUSHAT_ONLAYN_PAGE,
  );
  assert(parsed.ok, "fortieth production definition valid");
  assert(parsed.definition.slug === FORTIETH_PAGE_SLUG, "fortieth page slug");
  assert(parsed.definition.playlistSlug === FORTIETH_PLAYLIST_SLUG, "fortieth playlistSlug exact");
  assert(parsed.definition.h1 === FORTIETH_PAGE_H1, "fortieth h1 exact");
  assert(parsed.definition.title === FORTIETH_PAGE_TITLE, "fortieth title is TZ Meta Title");
  assert(parsed.definition.title !== parsed.definition.h1, "fortieth title !== h1");
  assert(
    parsed.definition.description === FORTIETH_PAGE_DESCRIPTION,
    "fortieth description equals TZ meta string",
  );
  assert(parsed.definition.intro.length === 3, "fortieth page has three intro paragraphs");
  assert(
    parsed.definition.intro[0] === FORTIETH_EXPECTED_INTRO[0] &&
      parsed.definition.intro[1] === FORTIETH_EXPECTED_INTRO[1] &&
      parsed.definition.intro[2] === FORTIETH_EXPECTED_INTRO[2],
    "fortieth intro verbatim",
  );
  assert(parsed.definition.sections.length === 8, "fortieth page has 8 sections");
  assert(
    parsed.definition.sections.map((section) => section.title).join("\n") ===
      FORTIETH_EXPECTED_SECTION_TITLES.join("\n"),
    "fortieth page 8 section titles verbatim",
  );
  assert(parsed.definition.faq.length === 7, "fortieth page has 7 FAQ items");
  assert(
    parsed.definition.faq.every(
      (item, index) =>
        item.question === FORTIETH_EXPECTED_FAQ[index].question &&
        item.answer === FORTIETH_EXPECTED_FAQ[index].answer,
    ),
    "fortieth page 7 FAQ verbatim",
  );
  assert(!("internalLinks" in parsed.definition), "fortieth page has no internalLinks");
  assert(!("cta" in parsed.definition), "fortieth page has no cta");
  for (const key of FORBIDDEN_COMPOSITION_KEYS) {
    assert(!(key in parsed.definition), `fortieth page has no static ${key}`);
  }

  const allTextChunks = [
    parsed.definition.h1,
    parsed.definition.title,
    parsed.definition.description,
    ...parsed.definition.intro,
    ...parsed.definition.sections.flatMap((section) => [
      section.title,
      ...(section.paragraphs ?? []),
      ...(section.blocks ?? []).flatMap((block) => {
        if (block.kind === "paragraph") return [block.text];
        if (block.kind === "list") return block.items ?? [];
        if (block.kind === "rich_paragraph") {
          return (block.segments ?? []).map((segment) => segment.text ?? segment.label ?? "");
        }
        if (block.kind === "heading") return [block.title];
        return [];
      }),
    ]),
    ...parsed.definition.faq.flatMap((item) => [item.question, item.answer]),
  ].join("\n");

  assert(!allTextChunks.includes(EIGHTEENTH_BOOKMARK_PHRASE), "fortieth definition has no bookmark phrase");
  assert(!allTextChunks.includes("🔖"), "fortieth definition has no bookmark emoji");
  assert(!allTextChunks.includes("SEO-самопроверка"), "fortieth definition has no SEO-самопроверка");
  assert(!allTextChunks.includes("[ЗДЕСЬ ВСТАВЛЯЕТСЯ"), "fortieth definition has no playlist placeholder");
  assert(!allTextChunks.includes("[PUBLIC PLAYLIST]"), "fortieth definition has no playlist marker");
  assert(!allTextChunks.includes("[ДАЛЕЕ"), "fortieth definition has no [ДАЛЕЕ leak");
  assert(!allTextChunks.includes("https://audiolad.ru/listens/"), "fortieth definition has no production listen URLs");
  assert(!allTextChunks.includes("https://"), "fortieth visible text has no raw https URLs");
  assert(!allTextChunks.includes("/listens/"), "fortieth visible text has no listen paths");
  assert(allTextChunks.includes(FORTIETH_EDITORIAL), "fortieth keeps baby-vs-kids editorial phrase");
  assert(allTextChunks.includes("не гарантирует"), "fortieth keeps no-guarantee wording");
  assert(!allTextChunks.includes("трек"), "fortieth has no track-count wording");

  const allRich = parsed.definition.sections
    .flatMap((section) => section.blocks ?? [])
    .filter((block) => block.kind === "rich_paragraph");
  const allLinks = allRich.flatMap((block) => (block.segments ?? []).filter((segment) => "href" in segment));
  assert(allLinks.length === 3, "fortieth page has three internal anchors");
  assert(allLinks.some((link) => link.href === FORTIETH_HUB_HREF && link.label === FORTIETH_HUB_LABEL), "fortieth page keeps kids sleep hub");
  assert(allLinks.some((link) => link.href === "/listens/uspokaivayushchaya-muzyka-dlya-detey-slushat-onlayn" && link.label === "успокаивающая музыка для детей"), "fortieth links uspok");
  assert(allLinks.some((link) => link.href === "/listens/kolybelnye-dlya-malyshey-slushat-onlayn" && link.label === "колыбельные для малышей"), "fortieth links lullabies");
  assert(new Set(allLinks.map((link) => link.href)).size === 3, "fortieth hrefs unique");
  assert(Boolean(getListenPageBySlug("detskaya-muzyka-dlya-sna-slushat-onlayn")), "kids hub destination exists");

  const contentSource = read("src/lib/seo/listens/content/muzyka-dlya-sna-dlya-malyshey-slushat-onlayn.ts");
  assert(!contentSource.includes("https://audiolad.ru/listens/"), "fortieth content file has no production listen URLs");
  assert(!contentSource.includes("https://"), "fortieth content file has no https://");
  assert(!contentSource.includes("SEO-самопроверка"), "fortieth content file has no SEO-самопроверка");
  assert(!contentSource.includes("[ЗДЕСЬ ВСТАВЛЯЕТСЯ"), "fortieth content file has no playlist placeholder");
  assert(!contentSource.includes("[PUBLIC PLAYLIST]"), "fortieth content file has no playlist marker");
  assert(!contentSource.includes("[ДАЛЕЕ"), "fortieth content file has no [ДАЛЕЕ");
  assert(!contentSource.includes("🔖"), "fortieth content file has no bookmark emoji");
  assert(!contentSource.includes(EIGHTEENTH_BOOKMARK_PHRASE), "fortieth content file has no bookmark phrase");
  assert(!contentSource.includes("primaryPractice"), "fortieth content file has no primaryPractice");
  assert(!contentSource.includes("CreatorPathsCta"), "fortieth content file has no CreatorPathsCta");
  assert(!contentSource.includes("ListenSignupCta"), "fortieth content file does not edit ListenSignupCta");
  assert(contentSource.includes(FORTIETH_EDITORIAL), "fortieth content file has editorial phrase");
  assert((contentSource.match(/href:/g) || []).length === 3, "fortieth content file has three hrefs");

  const slugs = listListenPageDefinitions().map((page) => page.slug);
  assert(slugs.includes(FORTIETH_PAGE_SLUG), "registry contains fortieth listen slug");
  assert(slugs.includes(THIRTY_NINTH_PAGE_SLUG), "registry still contains thirty-ninth listen slug");
  assert(slugs.length === 49, "registry contains all 49 listen slugs");
  assert(new Set(slugs).size === slugs.length, "listen slugs stay unique");
  assert(
    MUZYKA_DLYA_SNA_DLYA_MALYSHEY_SLUSHAT_ONLAYN_PAGE.playlistSlug === FORTIETH_PLAYLIST_SLUG,
    "fortieth page playlistSlug is kids sleep playlist",
  );
  assert(Boolean(getListenPageBySlug(FORTIETH_PAGE_SLUG)), "new slug resolves");

  const sitemap = mapListenPageDefinitionsToSitemapEntries(undefined, "https://audiolad.ru");
  const sitemapUrls = sitemap.map((entry) => entry.url);
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${FORTIETH_PAGE_SLUG}`).length === 1,
    "sitemap contains fortieth listen canonical exactly once",
  );
  assert(
    sitemapUrls.filter((url) => url === `https://audiolad.ru/listens/${THIRTY_NINTH_PAGE_SLUG}`).length === 1,
    "sitemap still contains thirty-ninth listen canonical exactly once",
  );

  const data = resolveListenPageFromPlaylist({
    definition: MUZYKA_DLYA_SNA_DLYA_MALYSHEY_SLUSHAT_ONLAYN_PAGE,
    loaded: {
      ok: true,
      detail: makePlaylist({
        playlist: {
          slug: FORTIETH_PLAYLIST_SLUG,
          title: "Музыка для сна детям | Колыбельные для малышей | Детская музыка для сна",
        },
      }),
    },
  });
  assert(data, "fortieth page resolves against kids sleep playlist");
  assert(data.playlist.playlist.slug === FORTIETH_PLAYLIST_SLUG, "resolved playlist slug is kids sleep");
  assert(data.path === `/listens/${FORTIETH_PAGE_SLUG}`, "fortieth path");
  assert(
    data.canonicalUrl === `https://audiolad.ru/listens/${FORTIETH_PAGE_SLUG}`,
    "fortieth canonical",
  );
  const graph = buildListenPageJsonLdGraph(data, "https://audiolad.ru");
  const serialized = JSON.stringify(graph);
  assert(serialized.includes('"Article"'), "fortieth JSON-LD Article");
  assert(serialized.includes('"WebPage"'), "fortieth JSON-LD WebPage");
  assert(serialized.includes('"Organization"'), "fortieth JSON-LD Organization");
  assert(serialized.includes('"BreadcrumbList"'), "fortieth JSON-LD BreadcrumbList");
  assert(serialized.includes('"ItemList"'), "fortieth JSON-LD ItemList");
  assert(serialized.includes('"FAQPage"'), "fortieth JSON-LD FAQPage");
  assert(!serialized.includes("MusicPlaylist"), "fortieth JSON-LD no MusicPlaylist");
  assert(!serialized.includes("AudioObject"), "fortieth JSON-LD no AudioObject");
  assert(!serialized.includes("primaryPractice"), "fortieth JSON-LD no primaryPractice");
  assert(!serialized.includes("Medical"), "fortieth JSON-LD no medical schema");
  assert(!serialized.includes(EIGHTEENTH_BOOKMARK_PHRASE), "fortieth JSON-LD has no bookmark phrase");
  assert(!serialized.includes("🔖"), "fortieth JSON-LD has no bookmark emoji");
  assert(!serialized.includes("https://audiolad.ru/listens/detskaya-muzyka-dlya-sna-slushat-onlayn"), "fortieth JSON-LD does not leak raw hub URL as visible label source");
}


