  assert(serialized.includes('"WebPage"'), "forty-seventh JSON-LD WebPage");
  assert(serialized.includes('"Organization"'), "forty-seventh JSON-LD Organization");
  assert(serialized.includes('"BreadcrumbList"'), "forty-seventh JSON-LD BreadcrumbList");
  assert(serialized.includes('"ItemList"'), "forty-seventh JSON-LD ItemList");
  assert(serialized.includes('"FAQPage"'), "forty-seventh JSON-LD FAQPage");
  assert(!serialized.includes("MusicPlaylist"), "forty-seventh JSON-LD no MusicPlaylist");
  assert(!serialized.includes("AudioObject"), "forty-seventh JSON-LD no AudioObject");
  assert(!serialized.includes("primaryPractice"), "forty-seventh JSON-LD no primaryPractice");
  assert(!serialized.includes("Medical"), "forty-seventh JSON-LD no medical schema");
  assert(!serialized.includes(EIGHTEENTH_BOOKMARK_PHRASE), "forty-seventh JSON-LD has no bookmark phrase");
  assert(!serialized.includes("🔖"), "forty-seventh JSON-LD has no bookmark emoji");
